399.     /// per-iteration state behind.
400.     fn link_one_user_page(
401.         parent: &mut Vmem,
402.         child: &mut Vmem,
403.         vaddr: PageAligned<VirtualAddress>,
404.         frame: FrameAddress,
405.         writable: bool,
406.         parent_cow: bool,
407.     ) -> Result<(), Error> {
