409.         // we can call [`UserFrame::share`] on it without risking a spurious decrement
410.         // of the parent's refcount if `share` itself returns an error. The parent's
411.         // page table still holds the original reference; only `child_handle` carries
412.         // the freshly-acquired one.
413.         let parent_handle: ManuallyDrop<UserFrame> = ManuallyDrop::new(UserFrame::new(frame));
414.         let child_handle: UserFrame = parent_handle.share()?;
415. 
416.         // The child installs the shared frame at the same virtual address. If the page is
417.         // logically writable the mapping is created RDWR so the subsequent CoW marking can
418.         // switch it to RO+CoW (mark_cow requires the entry to be writable); otherwise the
419.         // page is plain read-only with no CoW bit on either side. If `map` fails it drops
420.         // `child_handle`, releasing the refcount just acquired by `share`.
421.         let access: AccessPermission = if writable {
422.             AccessPermission::RDWR
