430.             // already CoW was shared writable by an earlier fork; re-marking it would fail
431.             // because mark_cow requires a writable PTE. The child is still mapped RDWR
432.             // (above) and marked CoW (below) so that a later write from the child resolves
433.             // as a copy-on-write fault instead of faulting fatally.
434.             if !parent_cow {
435.                 if let Err(e) = parent.mark_user_page_cow(vaddr) {
436.                     if let Err(re) = child.unmap(vaddr) {
437.                         warn!(
438.                             "link_user_pages(): partial rollback unmap failed (vaddr={vaddr:?}, \
439.                              error={re:?})"
440.                         );
441.                     }
442.                     return Err(e);
443.                 }
444.             }
445.             if let Err(e) = child.mark_user_page_cow(vaddr) {
446.                 // Only undo the parent's mark if this call installed it; a parent that was
447.                 // already copy-on-write must be left untouched.
448.                 if !parent_cow {
449.                     if let Err(re) = parent.unmark_user_page_cow(vaddr) {
