451.                             "link_user_pages(): partial rollback unmark failed (vaddr={vaddr:?}, \
452.                              error={re:?})"
453.                         );
454.                     }
455.                 }
456.                 if let Err(re) = child.unmap(vaddr) {
457.                     warn!(
458.                         "link_user_pages(): partial rollback unmap failed (vaddr={vaddr:?}, \
459.                          error={re:?})"
460.                     );
461.                 }
462.                 return Err(e);
