501.             let mut buf: [MaybeUninit<PageAligned<VirtualAddress>>; LINK_CHUNK] =
502.                 make_uninitialized_array();
503.             let mut count: usize = 0;
504.             let walk: Result<(), Error> = child.for_each_user_mapping(|vaddr, _pte| {
