507.                     // without a parent counterpart was not installed by this call.
508.                     match parent.is_user_page_mapped(vaddr) {
509.                         Ok(true) => {
510.                             buf[count].write(vaddr);
511.                             count += 1;
512.                         },
513.                         Ok(false) => {},
514.                         Err(e) => return Err(e),
515.                     }
516.                 }
517.                 Ok(())
518.             });
519.             if let Err(e) = walk {
520.                 warn!("link_user_pages(): rollback walk failed (error={e:?})");
521.                 return;
522.             }
523.             if count == 0 {
524.                 return;
525.             }
526.             for slot in buf.iter().take(count) {
527.                 // SAFETY: `slot` was written above for indices < count.
528.                 let vaddr = unsafe { slot.assume_init_read() };
529.                 if let Err(re) = child.unmap(vaddr) {
530.                     warn!(
531.                         "link_user_pages(): rollback unmap failed (vaddr={vaddr:?}, error={re:?})"
532.                     );
533.                 }
534.             }
535.             if count < LINK_CHUNK {
536.                 return;
537.             }
538.         }
539.     }
