                     &&& (!spec_is_cow_write_fault(error_code)
                             || !spec_is_user_addr(page_base(fault_addr as nat))
                             || !old(vmem)@.user_mapped(page_base(fault_addr as nat))
                             || !old(vmem)@.user[page_base(fault_addr as nat)].cow)
                 },
                 Err(_) => final(vmem)@ == old(vmem)@,
             },
     )]
