708.     pub fn alloc_upages(
709.         &mut self,
710.         vmem: &mut Vmem,
711.         mut vaddr: PageAligned<VirtualAddress>,
712.         access: AccessPermission,
713.         clear: bool,
714.         nframes: usize,
715.         uframes: &mut Vec<UserFrame>,
716.     ) -> Result<(), Error> {
717.         trace!("vaddr={:?}, nframes={}", vaddr, nframes);
718. 
719.         // The caller-supplied buffer must be empty; stale frames would cause double-mapping.
720.         if !uframes.is_empty() {
721.             let reason: &str = "caller-supplied uframes vector is not empty";
722.             error!("{reason}");
723.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
724.         }
725.         if uframes.capacity() < nframes {
726.             let reason: &str = "caller-supplied uframes vector has insufficient capacity";
727.             error!("{reason}");
728.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
729.         }
730. 
731.         // Validate that nframes is positive and the full range lies in user space.
732.         let range_size: usize = nframes.checked_mul(mem::PAGE_SIZE).ok_or_else(|| {
733.             let reason: &str = "range size overflow";
734.             error!("{reason} (nframes={nframes})");
735.             Error::new(ErrorCode::InvalidArgument, reason)
736.         })?;
737.         if !Vmem::is_user_region(vaddr.into_inner(), range_size) {
738.             let reason: &str = "range is not entirely in user space";
739.             error!("{reason} (vaddr={vaddr:?}, nframes={nframes})");
740.             return Err(Error::new(ErrorCode::BadAddress, reason));
741.         }
742. 
743.         // Check that none of the pages in the range are already mapped.
744.         let mut check_addr: PageAligned<VirtualAddress> = vaddr;
745.         let mut checked_count: usize = 0;
746.         while checked_count < nframes {
747.             if vmem.is_user_page_mapped(check_addr)? {
748.                 let reason: &str = "page already mapped in range";
749.                 error!("{reason} (vaddr={check_addr:?})");
750.                 return Err(Error::new(ErrorCode::ResourceBusy, reason));
751.             }
752.             check_addr = PageAligned::from_raw_value(
753.                 check_addr
754.                     .into_raw_value()
755.                     .checked_add(mem::PAGE_SIZE)
756.                     .ok_or_else(|| {
757.                         let reason: &str = "address overflow in range check";
758.                         error!("{reason} (check_addr={check_addr:?})");
759.                         Error::new(ErrorCode::BadAddress, reason)
760.                     })?,
761.             )?;
762.             checked_count += 1;
763.         }
764. 
765.         // SAFETY: the kernel is single-threaded and runs with interrupts disabled; no concurrent
766.         // or re-entrant access to the physical memory manager is possible.
767.         let alloc_result: Result<(), Error> =
768.             unsafe { PhysMemoryManager::get_mut() }.alloc_many_user_frames(nframes, uframes);
769.         if let Err(e) = alloc_result {
770.             uframes.clear();
771.             return Err(e);
772.         }
773. 
774.         let start_vaddr: PageAligned<VirtualAddress> = vaddr;
775.         let mut mapped_count: usize = 0;
776.         let mut map_error: Result<(), Error> = Ok(());
777. 
778.         {
779.             let mut drain = uframes.drain(..);
780.             loop {
781.                 let uframe: UserFrame = match drain.next() {
782.                     Some(uframe) => uframe,
783.                     None => break,
784.                 };
785. 
786.                 if let Err(e) = vmem.map(uframe, vaddr, access) {
787.                     map_error = Err(e);
788.                     break;
789.                 }
790.                 mapped_count += 1;
791.                 if clear {
792.                     if let Err(e) = vmem.memset(vaddr, 0) {
793.                         map_error = Err(e);
794.                         break;
795.                     }
796.                 }
797.                 match PageAligned::from_raw_value(vaddr.into_raw_value() + mem::PAGE_SIZE) {
798.                     Ok(next) => vaddr = next,
799.                     Err(e) => {
800.                         map_error = Err(e);
801.                         break;
802.                     },
803.                 }
804.             }
805.         }
806. 
807.         if let Err(e) = map_error {
808.             // Rollback: unmap all pages that were successfully mapped.
809.             let mut rollback_addr: PageAligned<VirtualAddress> = start_vaddr;
810.             let mut rollback_count: usize = 0;
811.             while rollback_count < mapped_count {
812.                 if let Err(re) = self.try_unmap_upage(vmem, rollback_addr) {
813.                     warn!(
814.                         "alloc_upages(): rollback failed (vaddr={rollback_addr:?}, error={re:?})"
815.                     );
816.                 }
817.                 rollback_addr = match PageAligned::from_raw_value(
818.                     rollback_addr.into_raw_value() + mem::PAGE_SIZE,
819.                 ) {
820.                     Ok(next) => next,
821.                     Err(_) => break,
822.                 };
823.                 rollback_count += 1;
824.             }
825.             return Err(e);
826.         }
827. 
828.         Ok(())
829.     }
